style.css:
@-moz-document regexp(".*") {
/* ----- ОСНОВНЫЕ ПЕРЕМЕННЫЕ (через :root) ----- */
    :root {
        --alarm-red: #d32f2f;
        --alarm-dark-red: #b71c1c;
        --alarm-panel-bg: #1e1e1e;
        --alarm-panel-light: #2c2c2c;
        --alarm-text: #e0e0e0;
        --alarm-border: #444;
        --lowvolt-green: #2e7d32;
        --lowvolt-blue: #1565c0;
        --alert-glow: 0 0 10px rgba(211, 47, 47, 0.7);
    }

    /* ----- ОБЩИЙ ФОН И ТЕКСТ ----- */
    body {
        background-color: var(--alarm-panel-bg) !important;
        background-image: 
            repeating-linear-gradient(45deg, 
                rgba(255, 0, 0, 0.03) 0px, 
                rgba(255, 0, 0, 0.03) 2px,
                transparent 2px, 
                transparent 8px),
            linear-gradient(rgba(0,0,0,0.7), rgba(0,0,0,0.7)) !important;
        color: var(--alarm-text) !important;
        font-family: 'Segoe UI', 'Arial', sans-serif !important;
        min-height: 100vh;
        position: relative;
    }

    /* Текст выделяется красным при выделении */
    ::selection {
        background: var(--alarm-red) !important;
        color: white !important;
        text-shadow: var(--alert-glow);
    }

    /* ----- ЗАГОЛОВКИ ----- */
    h1, h2, h3, h4, h5, h6 {
        color: #ffffff !important;
        text-shadow: 0 0 5px rgba(211, 47, 47, 0.5) !important;
        border-left: 4px solid var(--alarm-red) !important;
        padding-left: 15px !important;
    }

    /* ----- ССЫЛКИ ----- */
    a {
        color: var(--alarm-red) !important;
        text-decoration: none !important;
        transition: all 0.2s !important;
        font-weight: 500 !important;
        border-bottom: 1px dotted rgba(211, 47, 47, 0.5) !important;
    }

    a:hover {
        color: #ff5252 !important;
        text-shadow: var(--alert-glow) !important;
        border-bottom: 1px solid var(--alarm-red) !important;
    }

    /* ----- КНОПКИ ----- */
    button, 
    input[type="button"], 
    input[type="submit"], 
    input[type="reset"],
    .button,
    .btn {
        background: linear-gradient(to bottom, #3a3a3a, #1a1a1a) !important;
        border: 1px solid var(--alarm-border) !important;
        color: var(--alarm-text) !important;
        padding: 8px 16px !important;
        border-radius: 3px !important;
        font-weight: bold !important;
        text-transform: uppercase !important;
        letter-spacing: 0.5px !important;
        box-shadow: inset 0 0 5px rgba(0,0,0,0.5), 0 2px 3px rgba(0,0,0,0.3) !important;
        cursor: pointer !important;
        transition: all 0.15s !important;
        position: relative !important;
        overflow: hidden !important;
    }

    button:hover,
    input[type="button"]:hover,
    input[type="submit"]:hover,
    .button:hover,
    .btn:hover {
        background: linear-gradient(to bottom, #4a4a4a, #2a2a2a) !important;
        border-color: var(--alarm-red) !important;
        box-shadow: inset 0 0 8px rgba(211, 47, 47, 0.3), var(--alert-glow) !important;
        color: white !important;
    }

    button:active,
    input[type="button"]:active,
    input[type="submit"]:active,
    .button:active,
    .btn:active {
        background: #1a1a1a !important;
        box-shadow: inset 0 2px 5px rgba(0,0,0,0.8) !important;
        transform: translateY(1px) !important;
    }

    /* Опасные/красные кнопки (например, удалить) */
    button.danger,
    .btn-danger,
    [class*="danger"],
    [class*="delete"] {
        background: linear-gradient(to bottom, #b71c1c, #7f0000) !important;
        border-color: #ff8a80 !important;
        color: white !important;
    }

    button.danger:hover,
    .btn-danger:hover,
    [class*="danger"]:hover,
    [class*="delete"]:hover {
        background: linear-gradient(to bottom, #d32f2f, #b71c1c) !important;
        box-shadow: var(--alert-glow), inset 0 0 10px rgba(255,255,255,0.3) !important;
    }

    /* ----- ПОЛЯ ВВОДА ----- */
    input[type="text"],
    input[type="password"],
    input[type="email"],
    input[type="search"],
    input[type="number"],
    textarea,
    select {
        background-color: #2d2d2d !important;
        border: 1px solid #555 !important;
        color: var(--alarm-text) !important;
        padding: 8px !important;
        border-radius: 2px !important;
        box-shadow: inset 0 0 5px rgba(0,0,0,0.5) !important;
        transition: border 0.2s, box-shadow 0.2s !important;
    }

    input:focus,
    textarea:focus,
    select:focus {
        border-color: var(--alarm-red) !important;
        box-shadow: inset 0 0 8px rgba(211, 47, 47, 0.4), var(--alert-glow) !important;
        outline: none !important;
    }

    /* Чекбоксы и радио (стилизация с трудом, но меняем цвет акцента) */
    input[type="checkbox"],
    input[type="radio"] {
        accent-color: var(--alarm-red) !important;
    }

    /* ----- ТАБЛИЦЫ ----- */
    table {
        background-color: #252525 !important;
        color: var(--alarm-text) !important;
        border-collapse: collapse !important;
        border: 1px solid #444 !important;
    }

    th {
        background-color: #1e1e1e !important;
        color: white !important;
        font-weight: bold !important;
        text-transform: uppercase !important;
        letter-spacing: 0.5px !important;
        border-bottom: 2px solid var(--alarm-red) !important;
        padding: 12px !important;
    }

    td {
        border: 1px solid #3a3a3a !important;
        padding: 8px !important;
    }

    tr:nth-child(even) {
        background-color: #2a2a2a !important;
    }

    tr:hover {
        background-color: #333 !important;
        box-shadow: inset 0 0 5px rgba(211, 47, 47, 0.2) !important;
    }

    /* ----- СКРОЛЛБАР (WebKit) ----- */
    ::-webkit-scrollbar {
        width: 12px !important;
        height: 12px !important;
        background-color: #1a1a1a !important;
    }

    ::-webkit-scrollbar-track {
        background: #2d2d2d !important;
        border-left: 1px solid #444 !important;
        box-shadow: inset 0 0 5px black !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(45deg, #4a4a4a, #2a2a2a) !important;
        border-radius: 0 !important;
        border: 1px solid #555 !important;
        box-shadow: inset 0 0 5px rgba(0,0,0,0.7) !important;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: linear-gradient(45deg, #6a6a6a, #3a3a3a) !important;
        border-color: var(--alarm-red) !important;
    }

    ::-webkit-scrollbar-corner {
        background: #1a1a1a !important;
    }

    /* ----- ДЕКОРАТИВНЫЕ ЭЛЕМЕНТЫ СИГНАЛИЗАЦИИ (фиксированные) ----- */
    
    /* Мигающий индикатор "ТРЕВОГА" в левом верхнем углу */
    body::before {
        content: "⚠ ТРЕВОГА ⚠";
        position: fixed;
        top: 10px;
        left: 20px;
        background: rgba(0, 0, 0, 0.7);
        color: #ff3333;
        font-weight: bold;
        font-size: 14px;
        padding: 6px 12px;
        border: 2px solid #b71c1c;
        border-radius: 3px;
        box-shadow: var(--alert-glow);
        z-index: 2147483647;
        pointer-events: none;
        text-shadow: 0 0 8px red;
        animation: alarm-blink 1.5s infinite;
        backdrop-filter: blur(2px);
        font-family: 'Courier New', monospace;
        letter-spacing: 2px;
    }

    /* Индикатор "СЛАБОТОЧКА" справа вверху */
    body::after {
        content: "◈ СЛАБОТОЧНЫЕ СЕТИ ◈";
        position: fixed;
        top: 10px;
        right: 20px;
        background: rgba(0, 0, 0, 0.6);
        color: #4fc3f7;
        font-weight: bold;
        font-size: 12px;
        padding: 5px 10px;
        border: 1px solid #1565c0;
        border-radius: 3px;
        box-shadow: 0 0 8px rgba(21, 101, 192, 0.5);
        z-index: 2147483647;
        pointer-events: none;
        backdrop-filter: blur(2px);
        font-family: 'Courier New', monospace;
        letter-spacing: 1px;
        border-left: 4px solid #2e7d32;
        animation: pulse-blue 3s infinite;
    }

    /* Анимация мигания тревоги */
    @keyframes alarm-blink {
        0%, 100% { opacity: 1; box-shadow: 0 0 15px red; }
        50% { opacity: 0.7; box-shadow: 0 0 5px red; }
    }

    @keyframes pulse-blue {
        0%, 100% { opacity: 0.9; box-shadow: 0 0 5px #1565c0; }
        50% { opacity: 1; box-shadow: 0 0 12px #1565c0; }
    }

    /* Полоса кабель-канала по нижнему краю (эффект проводов) */
    html::before {
        content: "";
        position: fixed;
        bottom: 0;
        left: 0;
        right: 0;
        height: 6px;
        background: repeating-linear-gradient(90deg,
            #b71c1c 0px,
            #b71c1c 10px,
            #2e7d32 10px,
            #2e7d32 20px,
            #1565c0 20px,
            #1565c0 30px,
            #ffb300 30px,
            #ffb300 40px,
            #b71c1c 40px,
            #b71c1c 50px);
        box-shadow: 0 -2px 5px rgba(0,0,0,0.5);
        z-index: 2147483646;
        pointer-events: none;
        border-top: 1px solid #444;
    }

    /* Тонкая красная линия по левому краю (как шлейф сигнализации) */
    html::after {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        bottom: 0;
        width: 3px;
        background: linear-gradient(to bottom, 
            #ff0000 0%, 
            #ff0000 20%, 
            transparent 20%,
            transparent 40%,
            #ff0000 40%,
            #ff0000 60%,
            transparent 60%,
            transparent 80%,
            #ff0000 80%,
            #ff0000 100%);
        background-size: 100% 30px;
        box-shadow: 0 0 8px red;
        z-index: 2147483646;
        pointer-events: none;
    }

    /* ----- ПРОГРЕСС-БАРЫ И ИНДИКАТОРЫ ЗАГРУЗКИ ----- */
    progress,
    [role="progressbar"],
    .progress-bar {
        accent-color: var(--alarm-red) !important;
        border: 1px solid #555 !important;
        background-color: #1e1e1e !important;
        border-radius: 0 !important;
        height: 20px !important;
    }

    progress::-webkit-progress-value {
        background: repeating-linear-gradient(45deg,
            var(--alarm-red) 0px,
            var(--alarm-red) 5px,
            #b71c1c 5px,
            #b71c1c 10px) !important;
    }

    progress::-webkit-progress-bar {
        background-color: #2d2d2d !important;
        box-shadow: inset 0 0 5px black !important;
    }

    /* ----- КОД И ПРЕДВАРИТЕЛЬНОЕ ФОРМАТИРОВАНИЕ (как панель) ----- */
    code, pre {
        background-color: #1a1a1a !important;
        color: #ff8a80 !important;
        border: 1px solid #444 !important;
        border-left: 3px solid var(--alarm-red) !important;
        padding: 10px !important;
        font-family: 'Courier New', monospace !important;
        box-shadow: inset 0 0 10px rgba(0,0,0,0.7) !important;
    }

    /* ----- БЛОКИ ЦИТАТ И ВЫДЕЛЕНИЯ ----- */
    blockquote {
        background-color: #252525 !important;
        border-left: 5px solid var(--alarm-red) !important;
        padding: 15px !important;
        color: #ccc !important;
        box-shadow: 0 0 8px rgba(0,0,0,0.5) !important;
    }

    /* ----- МЕНЮ И НАВИГАЦИЯ (общие стили) ----- */
    nav, .nav, .menu, .navbar {
        background-color: #1e1e1e !important;
        border-bottom: 2px solid var(--alarm-red) !important;
        box-shadow: 0 2px 5px rgba(0,0,0,0.5) !important;
    }

    /* ----- КУРСОР В ВИДЕ ПРИЦЕЛА (как на панели) ----- */
    body {
        cursor: crosshair !important;
    }

    a, button, input, select, textarea, [role="button"] {
        cursor: pointer !important; /* Возвращаем для кликабельных */
    }

    /* Мелкие улучшения для слаботочных акцентов */
    .badge, .tag, .label {
        background-color: #333 !important;
        color: white !important;
        border-radius: 3px !important;
        padding: 3px 8px !important;
        border: 1px solid var(--alarm-border) !important;
        box-shadow: inset 0 0 3px black !important;
    }

    /* Иногда встречаются элементы с классом 'success' - делаем их зелеными (слаботочка) */
    .success, .ok, .good {
        color: #81c784 !important;
        border-color: #2e7d32 !important;
    }

    .error, .fail, .wrong {
        color: #ef9a9a !important;
        border-color: var(--alarm-red) !important;
    }
}
